@push('scripts')<script src="{{ asset('js/product-editor.js') }}" defer></script><script>(()=>{const form=document.getElementById('productForm'),input=document.getElementById('fileInput'),zone=document.getElementById('dropzone'),list=document.getElementById('fileList'),ids=document.getElementById('uploadIds'),format=document.getElementById('fileFormat'),select=document.getElementById('fileFormatSelect'),manual=document.getElementById('fileFormatManual'),confirmBox=document.getElementById('formatConfirm'),confirmed=document.getElementById('formatConfirmed'),page=document.getElementById('pageCount');let uploaded=[];const csrf='{{ csrf_token() }}';function setFormat(v,auto=false){v=(v||'').trim().toLowerCase();if(v&&!v.startsWith('.'))v='.'+v;format.value=v;select.value=Array.from(select.options).some(o=>o.value===v)?v:'';manual.value=select.value?'':v;if(auto){confirmBox.hidden=false;confirmed.checked=false}else{confirmBox.hidden=true;confirmed.checked=true}}async function addFiles(files){for(const file of Array.from(files||[])){const row=document.createElement('div');row.className='pc3-file';row.innerHTML='<span>'+file.name.split('.').pop().toUpperCase()+'</span><div><b></b><small>در حال بررسی...</small></div><i>…</i>';row.querySelector('b').textContent=file.name;list.appendChild(row);try{if(!/\.(pdf|doc|docx|ppt|pptx)$/i.test(file.name)||file.size>209715200)throw Error('فقط PDF، DOC، DOCX، PPT، PPTX و حداکثر ۲۰۰MB مجاز است.');const fd=new FormData();fd.append('file',file);const r=await fetch('{{ route('admin.products.uploads.store') }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},body:fd});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.message||'آپلود ناموفق بود');(d.files||[]).forEach(f=>{uploaded.push(f.id);if(!format.value&&f.format){setFormat(f.format,true);if(f.page_count&&!page.value)page.value=f.page_count}});row.querySelector('small').textContent='آماده ثبت';row.querySelector('i').textContent='✓';render()}catch(e){row.querySelector('small').textContent=e.message;row.querySelector('i').textContent='!'}}}function render(){ids.innerHTML=uploaded.map(id=>'<input type="hidden" name="upload_ids[]" value="'+id+'">').join('')}select.onchange=()=>setFormat(select.value,false);manual.oninput=()=>setFormat(manual.value,false);input?.addEventListener('change',e=>addFiles(e.target.files));['dragenter','dragover'].forEach(x=>zone?.addEventListener(x,e=>{e.preventDefault();zone.classList.add('over')}));['dragleave','drop'].forEach(x=>zone?.addEventListener(x,e=>{e.preventDefault();zone.classList.remove('over')}));zone?.addEventListener('drop',e=>addFiles(e.dataTransfer.files));form?.addEventListener('submit',e=>{if(!uploaded.length){e.preventDefault();alert('حداقل یک فایل محصول انتخاب کنید.');return}if(!format.value){e.preventDefault();alert('فرمت فایل اصلی را انتخاب کنید یا فایل را دوباره بارگذاری کنید تا سیستم آن را تشخیص دهد.');return}if(confirmBox&&!confirmBox.hidden&&!confirmed.checked){e.preventDefault();alert('لطفاً فرمت تشخیص‌داده‌شده را تأیید کنید.')}})})();</script>@endpush
